export function glossaryConflicts(
  entries: readonly ClimbingGlossaryEntry[] = CLIMBING_GLOSSARY,
): string[] {
  const seen = new Map<string, ClimbingGlossaryEntry>();
  const conflicts: string[] = [];
  for (const entry of entries) {
    for (const source of entry.source) {
      for (const category of entry.categories) {
        const normalized = entry.caseSensitive ? source : source.toLocaleLowerCase('en-US');
        const key = `${category}\0${entry.match}\0${normalized}`;
        const previous = seen.get(key);
        const policyValue = entry.policy === 'translate' ? entry.target : entry.policy;
        const previousValue = previous?.policy === 'translate' ? previous.target : previous?.policy;
        if (previous && previousValue !== policyValue) {
          conflicts.push(`${category}:${source}:${previous.id}/${entry.id}`);
        } else {
          seen.set(key, entry);
        }
      }
    }
  }
  return conflicts;
}

